function ballSVG(color,face='01',forImg=false){ const [fx,fy,vb,inner]=FACES[face]; const [,, w,h]=vb.split(' ').map(Number); const id='h'+(svgUid++);
  return `${forImg?'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100" width="200" height="200">':'<svg viewBox="0 0 100 100" width="100%" height="100%" aria-hidden="true">'}<defs><pattern id="${id}p" width="5" height="5" patternUnits="userSpaceOnUse"><circle cx="2.5" cy="2.5" r="1.05" fill="#1A1A1A" opacity=".35"/></pattern><mask id="${id}m"><circle cx="50" cy="50" r="49" fill="#fff"/><circle cx="40" cy="38" r="50" fill="#000"/></mask></defs><circle cx="50" cy="50" r="49" fill="${color}" stroke="#1A1A1A" stroke-width="2"/><circle cx="50" cy="50" r="48" fill="url(#${id}p)" mask="url(#${id}m)"/><svg x="${fx}" y="${fy}" width="${w}" height="${h}" viewBox="${vb}" overflow="visible">${inner}</svg></svg>`; }
