/* ================= B2 RECORD BOARD (physics) ================= */
const {Engine,Bodies,Composite,Body,Events,Query,Mouse,MouseConstraint}=Matter;
const engine=Engine.create(); engine.gravity.y=1.2;
const cv=$('#board'), ctx=cv.getContext('2d'); let W=0,H=0,walls=[],bodies=[],running=false,raf=0, focused=null;
const IMG={}; function ballImg(r){ const key=r.color+r.face; if(IMG[key]) return IMG[key]; const im=new Image(); im.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(ballSVG(COLORS[r.color],r.face,true)); IMG[key]=im; return im; }
const diameter=n=>Math.round(Math.min(96,44+(Math.max(n,2)-2)*5.2));
function sizeBoard(){ const r=$('#record').getBoundingClientRect(); W=r.width; H=r.height; const d=devicePixelRatio||1; cv.width=W*d; cv.height=H*d; ctx.setTransform(d,0,0,d,0,0);
  Composite.remove(engine.world,walls); const t=80, bottom=H; walls=[Bodies.rectangle(W/2,bottom+t/2,W*3,t,{isStatic:true}),Bodies.rectangle(-t/2,H/2,t,H*3,{isStatic:true}),Bodies.rectangle(W+t/2,H/2,t,H*3,{isStatic:true}),Bodies.rectangle(W/2,-t/2,W*3,t,{isStatic:true})]; Composite.add(engine.world,walls); }
let dropTimers=[];
function fillBoard(){ dropTimers.forEach(clearTimeout); dropTimers=[]; Composite.remove(engine.world,bodies); bodies=[];
  RECORDS.forEach((rec,i)=>{ const go=()=>{ const r=diameter(rec.people)/2; const b=Bodies.circle(r+Math.random()*(W-2*r), reduce? H-r-((i*37)%Math.max(1,H*.5)) : r+2, r,{restitution:.6,friction:.2,frictionAir:.012,density:rec.mine?.0015:.001}); b.rec=rec; bodies.push(b); Composite.add(engine.world,b); if(i<3) buzz(6); };
    if(reduce) go(); else dropTimers.push(setTimeout(go,120+i*60)); }); }
function draw(){ ctx.clearRect(0,0,W,H); for (const b of bodies){ const r=b.circleRadius*(b===focused?1.3:1), im=ballImg(b.rec); if(!im.complete) continue; ctx.save(); ctx.translate(b.position.x,b.position.y); ctx.rotate(b.angle); ctx.drawImage(im,-r,-r,r*2,r*2); ctx.restore(); } }
let last=0; function loop(t){ if(!running) return; const dt=Math.min(32,(t-last)||16); last=t; Engine.update(engine,dt); draw(); raf=requestAnimationFrame(loop); }
let lastBuzz=0; Events.on(engine,'collisionStart',e=>{ const now=performance.now(); if(now-lastBuzz<80) return; for(const p of e.pairs){ const v=Math.hypot(p.bodyA.velocity.x-p.bodyB.velocity.x,p.bodyA.velocity.y-p.bodyB.velocity.y); if(v>4){ buzz(6); lastBuzz=now; break; } } });
// drag & throw
const mouse=Mouse.create(cv); const mc=MouseConstraint.create(engine,{mouse,constraint:{stiffness:.2,render:{visible:false}}}); Composite.add(engine.world,mc);
mouse.element.removeEventListener('mousewheel',mouse.mousewheel); mouse.element.removeEventListener('DOMMouseScroll',mouse.mousewheel);
// tap → bubble (B2-05)
let downAt=null; cv.addEventListener('pointerdown',e=>{ downAt={x:e.clientX,y:e.clientY,t:performance.now()}; });
cv.addEventListener('pointerup',e=>{ if(!downAt) return; const moved=Math.hypot(e.clientX-downAt.x,e.clientY-downAt.y); const quick=performance.now()-downAt.t<300; downAt=null; if(moved>8||!quick) return;
  const rr=cv.getBoundingClientRect(); const pt={x:e.clientX-rr.left,y:e.clientY-rr.top}; const hit=Query.point(bodies,pt)[0];
  if(focused){ Body.setStatic(focused,false); focused=null; $('#bubble').classList.remove('on'); }
  if(hit){ focused=hit; Body.setStatic(hit,true); const r=hit.rec; const bb=$('#bubble');
    bb.innerHTML=`<div class="t"><span class="tag play">${r.play}</span>${r.mine?'<span class="tag lime" style="height:24px">내가 연 모임</span>':''}</div><div class="ln"><span class="ms">calendar_month</span>${r.date}</div><div class="ln"><span class="ms">location_on</span>${r.place}</div><div class="ln"><span class="ms">group</span>${r.people}명이 함께했어요</div>`;
    bb.style.left=Math.max(110,Math.min(W-110,hit.position.x))+'px'; bb.style.top=(hit.position.y-hit.circleRadius*1.3)+'px'; bb.classList.add('on'); buzz(10); } });
// tilt (desktop: pointer; mobile: device orientation after permission)
let tiltOn=false;
$('#record').addEventListener('pointermove',e=>{ if(tiltOn||e.pointerType!=='mouse'||mc.body) return; const r=$('#record').getBoundingClientRect(); engine.gravity.x=Math.max(-1,Math.min(1,((e.clientX-r.left)/r.width-.5)*2))*1.1; engine.gravity.y=1.2; });
function onOrient(ev){ const gx=(ev.gamma||0)/40, gy=(ev.beta||0)/40; engine.gravity.x=Math.max(-1.5,Math.min(1.5,gx))*1.2; engine.gravity.y=Math.max(-1.5,Math.min(1.5,gy))*1.2; }
let lastShake=0; function onMotion(ev){ const a=ev.accelerationIncludingGravity||{}; const m=Math.hypot(a.x||0,a.y||0,a.z||0)/9.8; const now=performance.now(); if(m>2.2&&now-lastShake>1000){ lastShake=now; shake(); } }
function shake(){ buzz([20,30,20]); bodies.forEach(b=>{ if(b!==focused) Body.setVelocity(b,{x:(Math.random()-.5)*14,y:-12-Math.random()*8}); }); }
/* "이거 누르세요" — a floating hint that points at the tilt button every time the board opens, until it is pressed */
function showTiltHint(){ const h=$('#tiltHint'), t=$('#tiltBtn'); if(!h||!t||tiltOn||location.hash!=='#record') return; const rb=$('#record').getBoundingClientRect(), bb=t.getBoundingClientRect(); h.style.top=(bb.bottom-rb.top+12)+'px'; h.style.right=Math.max(8,rb.right-bb.right-2)+'px'; h.style.setProperty('--ax',(bb.width/2-6+2)+'px'); h.classList.add('on'); t.classList.add('hinting'); }
function hideTiltHint(){ const h=$('#tiltHint'); if(h) h.classList.remove('on'); const t=$('#tiltBtn'); if(t) t.classList.remove('hinting'); }
$('#tiltBtn').addEventListener('click',async()=>{ hideTiltHint(); if(tiltOn){ shake(); return; } try{ if(typeof DeviceOrientationEvent!=='undefined'&&DeviceOrientationEvent.requestPermission){ const r=await DeviceOrientationEvent.requestPermission(); if(r!=='granted'){ toast('기울기 권한이 필요해요',{error:true}); return; } } if(typeof DeviceMotionEvent!=='undefined'&&DeviceMotionEvent.requestPermission){ try{ await DeviceMotionEvent.requestPermission(); }catch(e){} } }catch(e){}
  tiltOn=true; window.addEventListener('deviceorientation',onOrient); window.addEventListener('devicemotion',onMotion); $('#tiltTxt').textContent='흔들기'; $('#tiltBtn').querySelector('.ms').textContent='vibration'; toast('폰을 기울여 공을 굴려보세요'); });
function enterRecord(){ setTimeout(showTiltHint,450); $('#recBig').textContent=RECORDS.length; $('#recLine').textContent=`이번 달 ${RECORDS.length}번 놀았어요.`; requestAnimationFrame(()=>{ sizeBoard(); fillBoard(); if(!running){ running=true; last=performance.now(); raf=requestAnimationFrame(loop); } }); }
function leaveRecord(){ running=false; cancelAnimationFrame(raf); dropTimers.forEach(clearTimeout); if(focused){ Body.setStatic(focused,false); focused=null; } $('#bubble').classList.remove('on'); }
new ResizeObserver(()=>{ if($('#record').classList.contains('on')) sizeBoard(); }).observe($('#device'));

