function mapCard(place,addr){ const p=POI[place]||POI['충북대학교'], L=Math.max(-48,Math.min(0,172-p[0])), T=Math.max(-540,Math.min(0,100-p[1])); return `<div class="mapcard"><img class="mapsvg" style="left:${L}px;top:${T}px" src="${MAP_URL}" alt="충북대학교 주변 지도">${place?pinEl(place,p[0]+L,p[1]+T,true):''}${addr?`<span class="addr">${addr}</span>`:''}</div>`; }

