/* ---------- action delegation ---------- */
const ACT={};
document.addEventListener('click',e=>{ const a=e.target.closest('[data-act]'); if(!a) return; const fn=ACT[a.dataset.act]; if(fn){ e.preventDefault(); fn(a,e); } });
const GUARD={};
ACT.back=()=>{ const cur=(location.hash||'#home').slice(1); if(GUARD[cur]) GUARD[cur](); else goBack(); };

/* ---------- generic sheet ---------- */
const sheet2=document.getElementById('sheet2');
function openSheet2(html){ sheet2.innerHTML='<div class="handle"></div>'+html; dim.classList.add('on'); dim.style.background='rgba(26,26,26,.5)'; sheet2.classList.add('on'); }
function closeSheet2(){ sheet2.classList.remove('on'); dim.classList.remove('on'); }
dim.addEventListener('click',closeSheet2);
function reportSheet(title,reasons,done){ openSheet2(`<h3>${title}</h3><p class="t-fn c2" style="margin:0 0 8px">신고 내용은 상대에게 알려지지 않아요.</p>${reasons.map((r,i)=>`<button class="opt rp-opt" data-i="${i}" style="gap:12px"><span class="rd"></span>${r}</button>`).join('')}<div style="display:flex;gap:8px;margin-top:16px"><button class="btn" data-act="s2close">취소</button><button class="btn popup dis" id="s2ok">신고하기</button></div>`);
  let rsel=-1; const ok=document.getElementById('s2ok');
  sheet2.querySelectorAll('.rp-opt').forEach((b,i)=>b.addEventListener('click',()=>{ sheet2.querySelectorAll('.rp-opt').forEach(x=>x.classList.toggle('on',x===b)); rsel=i; ok.classList.remove('dis'); buzz(6); }));
  ok.onclick=()=>{ if(rsel<0) return; closeSheet2(); BLK.reports.unshift({w:title.startsWith('이 모임')?'모임 신고 · '+MEET.title:'사용자 신고 · '+title.replace(/(을|를) 신고할까요\?$/,''),r:reasons[rsel],d:todayTxt(),s:'접수 완료'}); done&&done(reasons[rsel]); }; }
ACT.s2close=closeSheet2;
function toastBall(msg,face='09',color='lime'){ toast(msg); const ic=document.getElementById('toastIcon'); ic.innerHTML=''; ic.appendChild(ballEl(COLORS[color],face,32)); }

