function meetCard(m){ const i=MEETS.indexOf(m); return `<div class="card mcard" data-act="openDetail" data-i="${i}" style="border-radius:16px"><div class="row" style="justify-content:space-between"><span class="pill-tag" style="background:var(--purple-50);color:var(--purple-600)">${m.tag}</span><span class="pill-tag" style="background:var(--bg-page);color:var(--grey-800)">${m.status==='closed'?'모집 마감':'모집중'}</span></div><div style="display:flex;flex-direction:column;gap:16px"><div class="t-h3">${m.title}</div><div style="display:flex;flex-direction:column;gap:8px"><div class="irow">${I('calendar_month')}${m.date}<span class="dot"></span>${m.time}</div><div class="irow">${I('location_on')}${m.place}<span class="dot"></span>${m.dist}</div><div class="irow">${I('group')}${m.count}<span class="dot"></span>${m.gender}</div></div></div></div>`; }
function renderMeet(){ const s=document.getElementById('meet');
  let body='';
  const shown=MEETS.filter(m=>!C.playFilter||m.tag===C.playFilter);
  const LS=(C.listState==='list'&&!shown.length)?'empty':C.listState;
  if(LS==='list') body=`<div style="display:flex;flex-direction:column;gap:20px;padding:0 24px 140px">${shown.map(meetCard).join('')}</div>`;
  if(LS==='error') body=`<div class="empty" id="emptyBox"><span id="eb"></span><div><div class="t-h3">모임을 불러오지 못했어요</div><p class="t-body c2" style="margin-top:8px">네트워크 연결을 확인하고<br>다시 시도해 주세요.</p></div><button class="btn md" style="width:auto;box-shadow:var(--shadow-2)" data-act="retryList">다시 시도</button></div>`;
  if(LS==='empty') body=`<div class="empty"><span id="eb"></span><div><div class="t-h3">조건에 맞는 모임이 없어요</div><p class="t-body c2" style="margin-top:8px">직접 놀이 모임을 열어볼까요?</p></div><button class="btn primary md" style="width:auto" data-act="openCreate">모임 열기</button></div>`;
  s.innerHTML=topbar('놀이 모임',{back:true,loc:true})+`<div style="background:var(--bg-page);min-height:100%"><div style="padding:16px 24px"><div class="seg4" id="seg4"><span class="knob"></span>${['500m','1km','3km','5km'].map((d,i)=>`<button data-act="dist" data-i="${i}">${d}</button>`).join('')}</div></div><div style="display:flex;gap:8px;padding:0 24px 16px">${['놀이','날짜','성별'].map(f=>f==='놀이'&&C.playFilter?`<button class="fchip" data-act="clearPlay" style="background:var(--lime-500)">${C.playFilter}${I('close')}</button>`:`<button class="fchip">${f}${I('arrow_upward_alt')}</button>`).join('')}</div>${body}</div>`;
  const eb=document.getElementById('eb'); if(eb) eb.appendChild(ballEl(COLORS[LS==='error'?'white':'lime'],LS==='error'?'11':'01',64)); requestAnimationFrame(()=>segKnob(false)); }
function segKnob(anim=true){ const seg=document.getElementById('seg4'); if(!seg) return; const b=seg.querySelectorAll('button')[C.dist], k=seg.querySelector('.knob'); if(!b||!b.offsetWidth) return; if(!anim) k.style.transition='none'; k.style.width=b.offsetWidth+'px'; k.style.transform=`translateX(${b.offsetLeft}px)`; if(!anim){ void k.offsetWidth; k.style.transition=''; } }
ACT.dist=b=>{ C.dist=+b.dataset.i; segKnob(true); buzz(6); };
ACT.retryList=()=>{ C.listState='list'; renderMeet(); };
ACT.clearPlay=()=>{ C.playFilter=''; C.listState='list'; buzz(6); renderMeet(); };
function openMeet(m){ Object.keys(MEET).forEach(k=>delete MEET[k]); Object.assign(MEET,m); go(m.mine?'host':'detail'); }
ACT.openDetail=b=>{ const i=+(b&&b.dataset&&b.dataset.i||0); openMeet(MEETS[i]||MEETS[0]); };
ACT.openCreate=()=>{ C.playFilter=''; C.form=blankForm(); C.editMode=false; C.formErr=false; go('create'); };

