  s.innerHTML=topbar('모임 개설 완료',{back:false})+`<div class="done"><div class="msg"><span id="cdBall"></span><div><div class="t-h2">모임이 열렸어요!</div><div class="t-body c2" style="margin-top:8px">이제 함께 놀 사람들을 기다려볼까요?</div></div></div><div class="card" style="width:100%;padding:16px;display:flex;flex-direction:column;gap:16px"><div class="row" style="gap:12px"><span class="thumb" style="width:56px;height:56px" id="cdThumb"></span><div style="display:flex;flex-direction:column;gap:4px"><span><span class="pill-tag" style="background:var(--purple-50);color:var(--purple-600)">${f.play}</span></span><span class="t-head">${f.title}</span></div></div><div style="height:1px;background:var(--grey-200)"></div><div style="display:flex;flex-direction:column;gap:8px"><div class="irow" style="font-size:14px">${I('calendar_month')}${fmtDate(f.date).dot.replace(' (','. (')} ${fmtTime(f.time)}</div><div class="irow" style="font-size:14px">${I('location_on')}${f.place}</div><div class="irow" style="font-size:14px">${I('group')}최대 ${f.people}명</div></div></div></div>`+`<div style="padding:16px 24px calc(env(safe-area-inset-bottom,0px) + 24px);display:flex;flex-direction:column;gap:16px"><button class="btn primary" data-act="toHost">모임 상세 보기</button><button class="btn" style="box-shadow:var(--shadow-1)" data-act="toMeet">모임 목록으로</button></div>`;
