function renderDone(){ const s=document.getElementById('done');
  s.innerHTML=topbar('놀이 완료',{back:false})+`<div class="done"><div class="msg"><span id="dnBall"></span><div><div class="t-h2">오늘도 놀이 하나 복원 완료!</div><div class="t-body c2" style="margin-top:8px">함께 놀았던 오늘의 추억이 기록됐어요.</div></div></div><div class="card" style="width:100%;padding:16px;display:flex;align-items:center;gap:16px"><span class="thumb" id="dnThumb"></span><div style="display:flex;flex-direction:column;gap:4px"><span><span class="pill-tag" style="background:var(--purple-50);color:var(--purple-600)">얼음땡</span></span><span class="t-head">퇴근 후 얼음땡 한판!</span><span class="t-fn c2">2026년 10월 17일 (토)</span></div></div></div><div style="padding:16px 24px calc(env(safe-area-inset-bottom,0px) + 24px);display:flex;flex-direction:column;gap:16px;background:#F6F6F6;flex:1"><button class="btn primary" data-act="toRate">함께 논 사람 평가하기</button><button class="btn sec2" data-go="record">나의 놀이 기록 보기</button></div>`;
  document.getElementById('dnBall').appendChild(ballEl(COLORS.lime,'09',100)); document.getElementById('dnThumb').appendChild(ballEl(COLORS.sky,'04',44));
  if(!C.recorded){ C.recorded=true; RECORDS.push({play:'얼음땡',date:'10월 17일',place:'충북대 대운동장',people:Object.values(C.attend).filter(v=>v===0).length,mine:false,color:'sky',face:'04'}); store.set('records',RECORDS); renderHome(); setTimeout(stampCelebrate,500); } }
function stampCelebrate(){ const cel=document.getElementById('cel'), st=cel.querySelector('.st'), tx=cel.querySelector('.tx'), ok=cel.querySelector('.btn'); cel.classList.add('on'); [cel,st,tx,ok].forEach(n=>n.getAnimations().forEach(a=>a.cancel()));
  if(reduce){ [cel,st,tx,ok].forEach(n=>n.animate([{opacity:0},{opacity:1}],{duration:200,fill:'forwards'})); return; }
  cel.animate([{opacity:0},{opacity:1}],{duration:240,fill:'forwards'});
  st.animate([{opacity:0,transform:'rotate(-8deg) scale(1.9)'},{opacity:1,transform:'rotate(-8deg) scale(.93)',offset:.7},{opacity:1,transform:'rotate(-8deg) scale(1.03)',offset:.85},{opacity:1,transform:'rotate(-8deg) scale(1)'}],{duration:340,delay:200,easing:'cubic-bezier(.2,.7,.3,1)',fill:'both'});
  setTimeout(()=>{ buzz([20,40,30]); tone(260,.2,.12); document.getElementById('device').animate([{transform:'translateY(0)'},{transform:'translateY(4px)'},{transform:'translateY(-2px)'},{transform:'translateY(0)'}],{duration:160}); },440*MOTION);
  tx.animate([{opacity:0,transform:'translateY(12px)'},{opacity:1,transform:'translateY(0)'}],{duration:280,delay:600,easing:'ease-out',fill:'both'}); ok.animate([{opacity:0},{opacity:1}],{duration:240,delay:760,fill:'both'}); }
