function sendMsg(v){ const m={t:'me',v,time:nowTime(),fail:E.failNext}; E.failNext=false; E.room.msgs.push(m); if(!m.fail) E.room.listTime=m.time; const log=document.getElementById('chatlog'); log.insertAdjacentHTML('beforeend',msgHTML(m,E.room.msgs.length-1)); const el=log.lastElementChild; buzz(6);
  if(!reduce) el.querySelector('.bub').animate([{transform:'translateY(14px) scale(.9)',opacity:0},{transform:'translateY(-2px) scale(1.02)',opacity:1,offset:.7},{transform:'translateY(0) scale(1)',opacity:1}],{duration:280,easing:'ease-out'});
  if(m.fail&&!reduce){ setTimeout(()=>{ el.animate([{transform:'translateX(0)'},{transform:'translateX(-8px)'},{transform:'translateX(8px)'},{transform:'translateX(-6px)'},{transform:'translateX(6px)'},{transform:'translateX(0)'}],{duration:360}); buzz([30,40,30]); },300); }
  log.scrollTo({top:log.scrollHeight,behavior:'smooth'}); }
ACT.resend=b=>{ const i=+b.dataset.i, M=E.room.msgs; M[i].fail=false; M[i].time=nowTime(); E.room.listTime=M[i].time; const row=document.querySelector(`#chatlog .mme[data-i="${i}"]`); row.outerHTML=msgHTML(M[i],i); buzz(8); };
ACT.roomBack=()=>go('chats');
ACT.startPlay=()=>dialog({title:'놀이를 시작할까요?',body:'시작하면 참여자 모두의 워치에\n놀이 화면이 열려요.',face:'13',color:'lime',buttons:[{label:'취소'},{label:'시작하기',primary:true,onClick:countdown}]});
function countdown(){ const c=document.getElementById('rcount'), n=document.getElementById('rcountNum'); c.classList.add('on'); const seq=['3','2','1','놀이 시작!'];
  seq.forEach((s,i)=>setTimeout(()=>{ n.textContent=s; n.style.fontSize=i===3?'44px':'120px'; buzz(i===3?[20,40,30]:20); tone(i===3?660:440,.18,.1); n.getAnimations().forEach(a=>a.cancel()); n.animate(reduce?[{opacity:0},{opacity:1},{opacity:0}]:[{opacity:0,transform:'scale(0)'},{opacity:1,transform:'scale(1.15)',offset:.3},{opacity:1,transform:'scale(1)',offset:.5},{opacity:1,transform:'scale(1)',offset:.8},{opacity:0,transform:'scale(.9)'}],{duration:i===3?1400:900,fill:'forwards',noScale:true}); },i*1000));
  setTimeout(()=>{ c.classList.remove('on'); E.started[E.room.id]=true; E.room.msgs.push({t:'sys',v:'놀이가 시작됐어요. 즐겁게 놀아요!'}); renderRoom(); },4500); }
ACT.finishFromChat=()=>{ C.recorded=false; go('attend'); };
