function renderOnboard(){ const s=document.getElementById('onboard'); const from=C.obFromSplash; C.obFromSplash=false;
  s.innerHTML=`<div class="ob-track" id="obTrack">${OB.map((p,i)=>`<section class="ob-page" data-i="${i}" aria-label="온보딩 ${i+1}/4"><div class="ob-hero"><div class="ob-art" style="position:absolute;left:50%;top:calc(var(--st) - 62px);width:393px;height:480px;margin-left:-196.5px">${p.art()}</div></div><div class="ob-text"><h2>${p.title}</h2><p>${p.body}</p></div></section>`).join('')}</div>
   <button class="ob-skip" id="obSkip" data-act="obDone">건너뛰기</button>
   <div class="ob-fixed"><div class="ob-dots" id="obDots">${OB.map(()=>'<i></i>').join('')}</div><button class="btn primary" id="obBtn" data-act="obNext">다음</button></div>`;
  s.style.setProperty('--st',getComputedStyle(document.querySelector('.hero')||s).getPropertyValue('--st')||'62px');
  s.querySelectorAll('.obball').forEach(e=>e.replaceWith(ballEl(COLORS[e.dataset.c],e.dataset.f,+e.dataset.s)));
  const track=s.querySelector('#obTrack'), pages=[...s.querySelectorAll('.ob-page')], dots=[...s.querySelectorAll('#obDots i')], btn=s.querySelector('#obBtn'), skip=s.querySelector('#obSkip');
  pages.forEach((pg,i)=>{ if(i>0||!reduce) pg.querySelectorAll('.ob-it').forEach(el=>el.classList.add('pre')); });
  const played=new Set(); let cur=0;
  /* fit the illustration area to the real screen height, so text and the fixed footer never collide on shorter phones */
  let K=1;
  function fit(){ const dv=document.getElementById('device'); const pr=document.createElement('div'); pr.style.cssText='position:absolute;visibility:hidden;height:max(env(safe-area-inset-top,0px),20px)'; s.appendChild(pr); const st=pr.offsetHeight||20; pr.remove();
    const full=st+418, textH=Math.max(...pages.map(p=>p.querySelector('.ob-text').offsetHeight)), footH=s.querySelector('.ob-fixed').offsetHeight;
    const hh=Math.max(280,Math.min(full,dv.clientHeight-textH-footH-16)); K=Math.min(hh/full,dv.clientWidth/393);
    pages.forEach(p=>{ p.querySelector('.ob-hero').style.height=hh+'px'; p.querySelector('.ob-art').style.top=(K*(st-62))+'px'; }); frame(); }
  window.__obFit=fit; if(!window.__obFitBound){ window.__obFitBound=true; window.addEventListener('resize',()=>{ if(window.__obFit&&document.getElementById('onboard').classList.contains('on')) window.__obFit(); }); }
  // continuous dots + parallax, all driven by one scroll position
  function frame(){ const w=track.clientWidth||1, x=track.scrollLeft/w;
    dots.forEach((d,i)=>{ const t=Math.max(0,1-Math.abs(x-i)); d.style.width=(8+16*t)+'px'; d.style.background=t>.5?'var(--purple-600)':'var(--grey-300)'; });
    pages.forEach((pg,i)=>{ const o=i-x; pg.querySelector('.ob-art').style.transform=`translateX(${o*-110}px) scale(${K})`; const tx=pg.querySelector('.ob-text'); tx.style.transform=`translateX(${o*-40}px)`; tx.style.opacity=String(Math.max(0,1-Math.abs(o)*1.4)); });
    const idx=Math.round(x); skip.style.opacity=idx>=3?'0':'1'; skip.style.pointerEvents=idx>=3?'none':'auto';
    if(idx!==cur){ cur=idx; btn.textContent=idx>=3?'땡땡이 시작하기':'다음'; if(!reduce) btn.animate([{opacity:.4},{opacity:1}],{duration:200}); } }
  let raf=0; track.addEventListener('scroll',()=>{ cancelAnimationFrame(raf); raf=requestAnimationFrame(frame); clearTimeout(track._st); track._st=setTimeout(settle,90); },{passive:true});
  function settle(){ const i=Math.round(track.scrollLeft/(track.clientWidth||1)); if(!played.has(i)){ played.add(i); obAnim(pages[i],i===0&&from); } }
  s._obGo=i=>{ track.scrollTo({left:i*track.clientWidth,behavior:reduce?'auto':'smooth'}); };
  s._obCur=()=>Math.round(track.scrollLeft/(track.clientWidth||1));
  fit(); if(document.fonts&&document.fonts.ready) document.fonts.ready.then(fit); frame(); requestAnimationFrame(()=>{ played.add(0); obAnim(pages[0],from); });
  // mouse drag paging (desktop preview)
  let sx=null,sl=0; track.addEventListener('pointerdown',e=>{ if(e.pointerType!=='mouse'||e.target.closest('button')) return; sx=e.clientX; sl=track.scrollLeft; track.style.scrollSnapType='none'; track.setPointerCapture(e.pointerId); });
  track.addEventListener('pointermove',e=>{ if(sx===null) return; track.scrollLeft=sl-(e.clientX-sx); });
  const up=e=>{ if(sx===null) return; const dx=e.clientX-sx; sx=null; const w=track.clientWidth; let i=Math.round(sl/w)+(dx<-50?1:dx>50?-1:0); i=Math.max(0,Math.min(3,i)); track.style.scrollSnapType=''; track.scrollTo({left:i*w,behavior:'smooth'}); };
  track.addEventListener('pointerup',up); track.addEventListener('pointercancel',up); }
/* tidy choreography: 3 beats per page — the main object, then the balls, then the character — one easing, even spacing */
function obAnim(pg,fromSplash){ const items=[...pg.querySelectorAll('.ob-it')]; if(reduce){ items.forEach(el=>el.classList.remove('pre')); return; }
  const base=fromSplash?320:0;
  if(fromSplash){ document.querySelector('#onboard .ob-fixed').animate([{opacity:0,transform:'translateY(40px)'},{opacity:1,transform:'translateY(0)'}],{duration:480,easing:'cubic-bezier(.2,.9,.3,1)',fill:'backwards'}); pg.querySelector('.ob-text').animate([{opacity:0,transform:'translateY(40px)'},{opacity:1,transform:'translateY(0)'}],{duration:480,delay:80,easing:'cubic-bezier(.2,.9,.3,1)',fill:'backwards'}); }
  const beat=el=>el.classList.contains('ob-char')||el.querySelector('.ob-badge')?2:(el.querySelector('.ball')&&!el.querySelector('.ob-dogam,.ob-map,.ob-watch'))?1:0;
  const counts=[0,0,0];
  items.forEach(el=>{ const g=beat(el), k=counts[g]++; const d=base+g*160+k*45; const r=el.style.transform;
    el.classList.remove('pre');
    const kf = g===0 ? [{opacity:0,transform:r+' translateY(18px) scale(.96)'},{opacity:1,transform:r}]
             : g===1 ? [{opacity:0,transform:r+' scale(.4)'},{opacity:1,transform:r+' scale(1.06)',offset:.65},{opacity:1,transform:r}]
                     : [{opacity:0,transform:r+' translateY(36px)'},{opacity:1,transform:r+' translateY(-10px)',offset:.6},{opacity:1,transform:r}];
    el.animate(kf,{duration:g===0?360:420,delay:d,easing:'cubic-bezier(.25,.9,.3,1)',fill:'backwards'}); });
  SPT.push(sT(()=>tone(380,.14,.06),base+330)); }
