function cropToData(c,size,cb){ if(c[0]==='IMG'){ const im=new Image(); im.onload=()=>{ const side=Math.min(im.width,im.height), sx=(im.width-side)/2, sy=Math.max(0,(im.height-side)*0.35); const cv=document.createElement('canvas'); cv.width=cv.height=size; cv.getContext('2d').drawImage(im,sx,sy,side,side,0,0,size,size); cb(cv.toDataURL('image/jpeg',.9)); }; im.src=c[1]; return; } const url=SPRITE[c[0]]; if(!url) return cb(null); const im=new Image(); im.onload=()=>{ const [k,a,tx,d,ty]=c; const sw=im.width*a, sh=im.height*d, side=Math.min(sw,sh), sx=im.width*tx+(sw-side)/2, sy=im.height*ty; const cv=document.createElement('canvas'); cv.width=cv.height=size; cv.getContext('2d').drawImage(im,sx,sy,side,side,0,0,size,size); cb(cv.toDataURL('image/jpeg',.9)); }; im.src=url; }
