/* --- 이용약관 · 개인정보 처리방침 --- */
const DOCS={
 terms:{title:'이용약관',date:'시행일 2026년 10월 1일',secs:[
  ['제1조 (목적)','이 약관은 땡땡이가 제공하는 동네 놀이 모임 서비스의 이용 조건과 절차, 이용자와 서비스의 권리·의무 및 책임 사항을 정하는 것을 목적으로 해요.'],
  ['제2조 (서비스 내용)','땡땡이는 이용자가 사는 동네의 놀이 모임을 열고 참여할 수 있게 하며, 함께 놀며 복원한 놀이를 기록하고 놀이 도감으로 보여주는 서비스를 제공해요.'],
  ['제3조 (회원 가입)','소셜 계정으로 로그인한 뒤 닉네임, 동네, 프로필 사진을 설정하면 가입이 완료돼요. 이용자는 정확한 정보를 입력해야 해요.'],
  ['제4조 (모임 개설과 참여)','이용자는 놀이 종류, 일시, 장소, 인원을 정해 모임을 열 수 있어요. 참여 조건(나이, 성별)이 맞지 않거나 모집이 마감된 모임에는 참여할 수 없어요.'],
  ['제5조 (이용자의 의무)','다른 이용자에게 욕설, 비하, 불쾌한 행동을 하거나 금전을 요구하는 행위, 광고·홍보 목적의 모임 개설은 금지돼요. 약속한 모임에 나가지 못하게 되면 미리 알려야 해요.'],
  ['제6조 (신고와 차단)','이용자는 불편한 이용자나 모임을 신고하거나 차단할 수 있어요. 신고 내용은 상대에게 알려지지 않으며, 운영 기준에 따라 이용이 제한될 수 있어요.'],
  ['제7조 (서비스 변경과 중단)','서비스는 운영상 필요한 경우 내용을 바꾸거나 일시 중단할 수 있어요. 이 경우 미리 공지로 알려드려요.'],
  ['제8조 (책임의 한계)','땡땡이는 이용자 사이의 모임 장소에서 일어난 사고에 대해 직접 책임지지 않아요. 안전한 장소에서 모이고 안전 수칙을 지켜 주세요.']]},
 privacy:{title:'개인정보 처리방침',date:'시행일 2026년 10월 1일',secs:[
  ['1. 수집하는 정보','소셜 로그인 정보(이름, 이메일), 닉네임, 프로필 사진, 동네 인증을 위한 위치 정보, 모임 참여 · 채팅 · 평가 기록을 수집해요.'],
  ['2. 이용 목적','회원 식별과 로그인, 동네 기반 모임 추천, 놀이 기록과 도감 제공, 신고 처리와 안전한 이용 환경 유지를 위해 사용해요.'],
  ['3. 위치 정보','현재 위치는 동네 인증과 가까운 모임 안내에만 사용하고, 인증이 끝나면 정확한 좌표는 저장하지 않아요. 위치 사용 권한은 기기 설정에서 언제든 끌 수 있어요.'],
  ['4. 보유 기간','회원 탈퇴 즉시 개인정보와 놀이 기록을 삭제해요. 다만 신고 처리 기록은 분쟁 해결을 위해 3개월 동안 보관해요.'],
  ['5. 제3자 제공','이용자의 동의가 있거나 법령에 따른 경우를 제외하고 개인정보를 외부에 제공하지 않아요.'],
  ['6. 이용자의 권리','이용자는 언제든 자신의 정보를 확인하고 수정하거나 탈퇴를 요청할 수 있어요. 마이 → 설정에서 직접 처리할 수 있어요.'],
  ['7. 문의','개인정보와 관련한 문의는 앱 내 공지사항에 안내된 창구로 보내 주세요.']]}};
function renderDoc(k){ const s=document.getElementById(k), d=DOCS[k];
  s.innerHTML=topbar(d.title)+`<div style="padding:24px 24px 8px"><div class="t-h2">${d.title}</div><div class="t-cap c3" style="margin-top:4px">${d.date}</div></div>`+d.secs.map(([h,p])=>`<div class="doc" style="padding:20px 24px;border-top:8px solid var(--bg-page)"><h3>${h}</h3><p>${p}</p></div>`).join('')+`<div class="t-cap c3" style="padding:16px 24px calc(env(safe-area-inset-bottom,0px) + 40px);background:var(--bg-page)">이 문서는 졸업전시 시연용 예시 문구예요.</div>`; }
