/* ================= on-screen keyboard (desktop preview only; phones use the native keyboard) ================= */
(function(){ const dev=document.getElementById('device'); const kb=document.createElement('div'); kb.className='kb'; kb.setAttribute('aria-hidden','true'); dev.appendChild(kb);
  const KO=[['ㅂ','ㅈ','ㄷ','ㄱ','ㅅ','ㅛ','ㅕ','ㅑ','ㅐ','ㅔ'],['ㅁ','ㄴ','ㅇ','ㄹ','ㅎ','ㅗ','ㅓ','ㅏ','ㅣ'],['ㅋ','ㅌ','ㅊ','ㅍ','ㅠ','ㅜ','ㅡ']];
  const SH={'ㅂ':'ㅃ','ㅈ':'ㅉ','ㄷ':'ㄸ','ㄱ':'ㄲ','ㅅ':'ㅆ','ㅐ':'ㅒ','ㅔ':'ㅖ'};
  const NUM=[['1','2','3','4','5','6','7','8','9','0'],['-','/',':',';','(',')','₩','&','@','"'],['.',',','?','!',"'"]];
  let target=null, shift=false, num=false, base='', jamo=[];
  const desktop=()=>matchMedia('(min-width:520px)').matches && matchMedia('(pointer:fine)').matches;
  function draw(){ const rows=num?NUM:KO; const key=c=>`<button data-k="${c}">${shift&&!num&&SH[c]?SH[c]:c}</button>`;
    kb.innerHTML=`<div class="r">${rows[0].map(key).join('')}</div><div class="r">${rows[1].map(key).join('')}</div><div class="r"><button class="fn wide${shift?' on':''}" data-k="shift"><span class="ms">${shift?'shift_lock':'shift'}</span></button>${rows[2].map(key).join('')}<button class="fn wide" data-k="bs"><span class="ms">backspace</span></button></div><div class="r"><button class="fn wide" data-k="num">${num?'한글':'123'}</button><button class="space" data-k="sp">스페이스</button><button class="ret" data-k="ret">${target&&target.closest('#room')?'전송':'검색'}</button></div>`; }
  function compose(){ const txt=window.Hangul? Hangul.assemble(jamo) : jamo.join(''); target.value=base+txt; target.dispatchEvent(new Event('input',{bubbles:true})); try{ target.setSelectionRange(target.value.length,target.value.length); }catch(e){} }
  function commit(){ base=target.value; jamo=[]; }
  function show(t){ target=t; base=t.value; jamo=[]; shift=false; num=false; draw(); kb.classList.add('on'); const room=t.closest('#room'); if(room){ room.classList.add('kbpad'); room.style.paddingBottom=kb.offsetHeight+'px'; const log=room.querySelector('#chatlog'); setTimeout(()=>log&&(log.scrollTop=log.scrollHeight),300); } else setTimeout(()=>t.scrollIntoView({block:'center',behavior:'smooth'}),60); }
  function hide(){ kb.classList.remove('on'); const room=document.getElementById('room'); if(room){ room.classList.remove('kbpad'); room.style.paddingBottom=''; } target=null; }
  document.addEventListener('focusin',e=>{ const t=e.target; if(!desktop()) return; if((t.tagName==='INPUT'&&!['date','time','checkbox','radio','range'].includes(t.type))||t.tagName==='TEXTAREA'){ if(target!==t) show(t); } });
  document.addEventListener('focusout',e=>{ setTimeout(()=>{ const a=document.activeElement; if(!a||!(a.tagName==='INPUT'||a.tagName==='TEXTAREA')) hide(); },0); });
  kb.addEventListener('pointerdown',e=>{ e.preventDefault(); const b=e.target.closest('button'); if(!b||!target) return; const k=b.dataset.k; buzz(4);
    if(k==='shift'){ shift=!shift; draw(); return; }
    if(k==='num'){ num=!num; shift=false; draw(); return; }
    if(k==='bs'){ if(jamo.length){ jamo.pop(); compose(); } else { target.value=target.value.slice(0,-1); base=target.value; target.dispatchEvent(new Event('input',{bubbles:true})); } return; }
    if(k==='sp'){ commit(); target.value+=' '; base=target.value; target.dispatchEvent(new Event('input',{bubbles:true})); return; }
    if(k==='ret'){ commit(); if(target.tagName==='TEXTAREA'){ target.value+='\n'; base=target.value; target.dispatchEvent(new Event('input',{bubbles:true})); return; } const f=target.closest('form'); if(f){ f.requestSubmit(); base=''; jamo=[]; } else { target.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',bubbles:true})); target.dispatchEvent(new Event('change',{bubbles:true})); } return; }
    const ch=shift&&!num&&SH[k]?SH[k]:k; if(num){ commit(); target.value+=ch; base=target.value; target.dispatchEvent(new Event('input',{bubbles:true})); } else { jamo.push(ch); compose(); } if(shift){ shift=false; draw(); } });
  // real typing resets the composition buffer
  document.addEventListener('keydown',e=>{ if(target&&e.isTrusted){ base=target.value; jamo=[]; setTimeout(()=>{ if(target){ base=target.value; } },0); } },true);
  window.addEventListener('hashchange',hide);
})();

/* iPhone home-screen app: the browser can report a window that is shorter than the real screen (the status-bar zone is left out),
   which leaves a blank band at the bottom. Measure several height sources and, when the shortfall is about the status bar, size the app to the full screen. */
function viewportInfo(){ const probe=(css)=>{ const e=document.createElement('div'); e.style.cssText='position:fixed;left:0;top:0;width:1px;visibility:hidden;pointer-events:none;'+css; document.body.appendChild(e); const v=Math.round(e.getBoundingClientRect().height); e.remove(); return v; };
  return {inner:innerHeight, outer:outerHeight, screenH:screen.height, screenW:screen.width, vv:window.visualViewport?Math.round(window.visualViewport.height):0, safeTop:probe('height:env(safe-area-inset-top,0px)'), safeBottom:probe('height:env(safe-area-inset-bottom,0px)'), vh:probe('height:100vh'), dvh:probe('height:100dvh'), lvh:probe('height:100lvh'), svh:probe('height:100svh'), pct:probe('height:100%'), standalone:navigator.standalone===true, dm:matchMedia('(display-mode: standalone)').matches}; }
function calcAppH(i){ const vis=Math.max(i.inner,i.vv||0,i.dvh||0,i.pct||0), tall=Math.max(i.screenH,i.screenW), tol=(i.safeTop||0)+6;
  const bigger=[i.vh||0,i.lvh||0].filter(v=>v>vis&&v<=tall).sort((x,y)=>y-x)[0]||0;
  if(tall-vis>0&&tall-vis<=tol) return tall;      /* short by about the status bar → whole screen */
  if(bigger&&bigger-vis<=tol) return bigger;
  return 0; }
function fitDevice(){ const root=document.documentElement; if(innerWidth>=520){ root.style.removeProperty('--appH'); return; } const h=calcAppH(viewportInfo()); if(h) root.style.setProperty('--appH',h+'px'); else root.style.removeProperty('--appH'); }
fitDevice(); [120,600,1600].forEach(t=>setTimeout(fitDevice,t)); addEventListener('resize',fitDevice); addEventListener('orientationchange',()=>setTimeout(fitDevice,250)); addEventListener('pageshow',fitDevice); document.addEventListener('visibilitychange',fitDevice); document.addEventListener('touchstart',fitDevice,{once:true,passive:true});
